responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "10번 줄에서 알 수 없는 스키마 버전을 읽었을 때 items를 빈 배열로 바꾸고 version 1로 덮어쓰도록 규정하여, 승인된 기술 제약인 '알 수 없는 스키마 버전은 원본 보존과 쓰기 차단으로 처리한다' 및 잘못된 저장 데이터 원본 보존 요구(R-3)와 정면으로 충돌합니다.",
      "suggestedDirection": "알 수 없는 스키마 버전 발견 시 빈 배열로 덮어쓰는 예외 규칙을 삭제하고, 승인 제약대로 기존 저장 데이터를 그대로 보존하며 추가 쓰기를 차단하도록 수정해야 합니다.",
      "relatedRequirementId": "R-3"
    }
  ],
  "suggestions": [
    "10번 줄의 스키마 버전 처리 문장을 승인된 기술 제약과 일치하도록 '모르는 스키마 버전은 원본 보존 및 쓰기 차단'으로 정정하세요."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 4, 8],
        "rationale": "물건명과 빌린 사람 입력, 공백 검증, 동일 물건명에 대한 고유 식별자 및 안전 정수 순번 부여 규칙이 구체적으로 명시되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "satisfied",
        "evidenceLines": [5, 9],
        "rationale": "선택한 단일 대상 ID에 대해서만 반환 상태로 변경하며 중복 호출 시 멱등성을 유지하는 규칙이 구체적으로 명시되어 있습니다."
      },
      {
        "requirementId": "R-3",
        "status": "missing",
        "evidenceLines": [6, 10],
        "rationale": "재접속 유지 및 손상 데이터 보존을 다루고 있으나, 10번 줄에서 모르는 스키마 버전을 감지했을 때 데이터를 빈 배열로 덮어쓰도록 하여 R-3 원본 보존 요구와 기술 제약을 위반하고 있습니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [1, 12],
        "rationale": "기획안이 미승인 제안임을 명시하고 키 이름과 세부 데이터 표현이 위임된 기술 제안임을 사용자 결정과 분리하여 정확히 기술했습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [10, 13],
        "rationale": "제외 기능은 준수하였으나 승인된 기술 제약인 '알 수 없는 스키마 버전은 원본 보존과 쓰기 차단'에 위배되는 덮어쓰기 동작이 10번 줄에 포함되어 있습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "스키마 위반 시 쓰기 차단 및 원본 보존을 선언한 문장과 모르는 버전을 빈 배열로 덮어쓴다는 문장이 10번 줄 내부에서 상호 모순을 일으킵니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "미확인 버전 로드 시 영속 데이터를 소실시키는 덮어쓰기 로직이 정의되어 있어 데이터 보존 무결성을 침해합니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [8, 9, 10],
        "rationale": "R-1, R-2의 동작 및 R-3의 단일 키 구조, 검증 순서, 커밋 전후 실패 처리에 대한 구체적인 판정 기준이 제시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [13],
        "rationale": "정착된 사용자 수정 요청 내역이 없는 초기 기획안 검토이므로 해당하지 않습니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [2, 3, 7, 12],
        "rationale": "상단에 쉬운 한국어 사용자 시나리오를 먼저 배치하고 기술 세부사항을 하단에 명확히 분리하여 기술했습니다."
      }
    ]
  }
}
